using NUnit.Framework;

[TestFixture]
public class StringServiceTests
{
    [Test]
    public void Concat_TwoStrings_ReturnsCombined()
    {
        // Arrange
        var service = new StringService();

        // Act
        var result = service.Concat("Hello", " World");

        // Assert
        Assert.That(result, Is.EqualTo("Hello World"));
    }
}

[Test]
public void Validate_User_Age_Range()
{
    var user = new User { Age = 25 };

    Assert.That(user.Age, Is.GreaterThan(18));
    Assert.That(user.Age, Is.LessThanOrEqualTo(100));
    Assert.That(user.Name, Is.Not.Null.And.Not.Empty);
    Assert.That(user.Email, Does.Contain("@"));
}
